// rules.mjs — turns capture metrics into parameter scores and concrete, justified suggestions.
// Every finding carries: evidence (what we measured), why (the principle), source (where it comes from),
// suggestion (what to change), and optionally cssPatch (so the mockup renderer can show it).

export const PARAMETERS = [
  { id: 'color', name: 'Color theory', blurb: 'Harmony, restraint, one accent doing one job, semantic use of colour.' },
  { id: 'accessibility', name: 'Accessibility', blurb: 'WCAG 2.2 AA: contrast, names, labels, focus, zoom, structure, targets.' },
  { id: 'placement', name: 'Placement of items', blurb: 'Where the eye lands first, where the primary action sits, reach and grouping.' },
  { id: 'space', name: 'Use of space', blurb: 'Rhythm, consistent spacing scale, margins, density appropriate to the job.' },
  { id: 'negative_space', name: 'Negative space', blurb: 'Breathing room that creates grouping and emphasis without boxes and rules.' },
  { id: 'ux_principles', name: 'UI/UX principles', blurb: "Nielsen's heuristics and the Laws of UX: Hick, Fitts, Jakob, Miller, Gestalt." },
  { id: 'typography', name: 'Typography & AI fonts', blurb: 'Typeface choice, scale, measure, leading, and whether the type reads as a default.' },
  { id: 'ai_look', name: 'Looks like typical AI', blurb: 'The cluster of generated-page tells, weighted by how strongly each separates weak from strong sites.' },
  { id: 'creativity', name: 'Creativity & concept', blurb: 'Is there an idea only this subject could own, or is it the category template?' },
  { id: 'responsive', name: 'Responsive consistency', blurb: 'Same design at 390, 768, 1440 and 1920: no overflow, no three-line headlines, readable type.' },
  { id: 'hierarchy', name: 'Visual hierarchy', blurb: 'One focal point per screen; headline-to-body ratio; what competes for attention.' },
  { id: 'copy', name: 'Copy & microcopy', blurb: 'Words are design content: specific headlines, specific buttons, no buzzwords.' },
  { id: 'motion', name: 'Motion & interaction', blurb: 'Reduced-motion respected, no transition:all, one orchestrated moment rather than scattered fades.' },
  { id: 'consistency', name: 'System consistency', blurb: 'Radius, shadow and spacing vocabularies are small and deliberate.' },
  { id: 'imagery', name: 'Imagery', blurb: 'Real pictures and media carry a page; decoration and placeholders do not.' },
  { id: 'craft', name: 'Craft & performance hygiene', blurb: 'Image dimensions, lazy loading, console errors, font loading.' },
];

const SEV = { P0: 3, P1: 2, P2: 1, P3: 0.5 };
const clamp = (v, a = 0, b = 10) => Math.max(a, Math.min(b, v));
const r1 = v => Math.round(v * 10) / 10;

// Fonts that read as "the framework shipped with it" when used for everything.
const DEFAULT_FONTS = ['inter', 'roboto', 'arial', 'helvetica', 'system-ui', '-apple-system', 'segoe ui', 'open sans', 'lato', 'poppins', 'montserrat', 'space grotesk', 'dm sans', 'plus jakarta sans', 'manrope', 'sans-serif', 'ui-sans-serif', 'times new roman', 'times', 'serif'];
const AI_FAVOURITE_FONTS = ['inter', 'space grotesk', 'dm sans', 'plus jakarta sans', 'manrope', 'poppins', 'outfit', 'sora', 'urbanist', 'playfair display', 'instrument serif', 'jetbrains mono', 'space mono'];

const SRC = {
  taste: 'taste-skill study of 247 One Page Love / Awwwards sites (Oct 2026)',
  anthropic: 'Anthropic frontend-design skill (anthropics/skills)',
  impeccable: 'impeccable slop detector (pbakaus/impeccable)',
  vercel: 'Vercel Web Interface Guidelines',
  wcag: 'WCAG 2.2',
  lawsux: 'Laws of UX (Yablonski)',
  nielsen: "Nielsen's 10 usability heuristics",
  bringhurst: 'Bringhurst, The Elements of Typographic Style',
  gestalt: 'Gestalt principles (proximity, similarity, common region)',
  fitts: "Fitts's law",
  hick: "Hick's law",
  miller: "Miller's law / chunking",
  jakob: "Jakob's law",
  restorff: 'Von Restorff (isolation) effect',
  designpref: 'DesignPref (Krippendorff alpha 0.25 among 20 pro designers)',
};

export function evaluate(capture) {
  const vps = capture.viewports.filter(v => v.metrics);
  if (!vps.length) throw new Error('No viewport captured successfully');
  const by = Object.fromEntries(vps.map(v => [v.name, v]));
  const primary = by.laptop || by.desktop || vps[vps.length - 1];
  const phone = by.phone;
  const M = primary.metrics, T = M.tells, S = M.selectors || {};
  const findings = [];
  let idc = 0;
  const ruleId = f => f.rule || `${f.param}.${f.title.toLowerCase().replace(/"[^"]*"/g, 'x').replace(/\d+(\.\d+)?(px|vw|%)?/g, 'n').replace(/[^a-z]+/g, '-').replace(/^-|-$/g, '')}`;
  const add = f => { findings.push({ id: `F${String(++idc).padStart(3, '0')}`, viewports: [primary.name], ...f, rule: ruleId(f) }); };
  const totalChars = Math.max(1, M.totalChars);
  const pct = (n, d = totalChars) => Math.round(100 * n / d);
  const fontList = Object.entries(M.fonts).sort((a, b) => b[1] - a[1]);
  const mainFont = fontList[0]?.[0] || 'unknown';
  const mainFontShare = fontList[0] ? fontList[0][1] / totalChars : 0;
  const sizes = Object.entries(M.fontSizes).map(([s, c]) => [+s, c]).sort((a, b) => a[0] - b[0]);
  const bodySize = M.bodySize || (sizes.length ? sizes.reduce((best, cur) => cur[1] > best[1] ? cur : best, sizes[0])[0] : 16);

  // ======================= COLOR =======================
  if (T.purpleGradient) add({ param: 'color', severity: 'P1', title: 'Purple/indigo-to-blue gradient', evidence: `${T.gradients} gradient fills; at least one in the 240–300° hue band (${T.gradientSamples.slice(0, 3).map(g => g.hues.join('→')).join(', ')}).`, why: 'This is the single most-cited visual tell of generated UI (Tailwind indigo-500 / violet defaults). Gradients appeared on 52% of weak sites vs 22% of strong ones in the study. It dates a page fast and says nothing about the subject.', source: `${SRC.taste}; ${SRC.impeccable}`, suggestion: 'Replace with one flat accent chosen from the subject (a material, a place, the product itself). Keep gradients only as photographic scrims.', cssPatch: (T.gradientSamples || []).map(g => g.sel ? (g.h <= 80 && g.w <= 400 ? `${g.sel}{background-image:none!important;background-color:var(--dc-accent,#1f4e5f)!important;}` : `${g.sel}{background-image:none!important;}`) : '').filter(Boolean).join('\n') + `\n${(S.gradientText || []).map(s => `${s}{background-image:none!important;background-color:transparent!important;color:inherit!important;-webkit-text-fill-color:currentColor!important;}`).join('\n')}` });
  else if (T.gradients >= 4) add({ param: 'color', severity: 'P2', title: 'Decorative gradients', evidence: `${T.gradients} non-scrim gradient fills.`, why: 'Gradient washes as decoration are the SaaS-card-kit default; strong sites use flat fields per section (median 2 distinct section grounds vs 1 on weak sites).', source: SRC.taste, suggestion: 'Flatten to solid colour fields; let a change of ground colour mark a new section instead of a gradient.', cssPatch: (S.gradients || []).map(s => `${s}{background-image:none!important;}`).join('\n') });
  if (T.gradientText > 0) add({ param: 'color', severity: 'P2', title: 'Gradient-clipped text', evidence: `${T.gradientText} elements use background-clip:text.`, why: 'Gradient text appeared on 13% of weak sites vs 2% of strong ones. It also fails contrast checks unpredictably across the gradient.', source: SRC.taste, suggestion: 'Set headline text in one ink colour; put the colour, if anywhere, in one object on the page.', cssPatch: (S.gradientText || []).map(s => `${s}{background-image:none!important;color:inherit!important;-webkit-text-fill-color:currentColor!important;}`).join('\n') });
  if (M.accentHues.length >= 4) add({ param: 'color', severity: 'P2', title: 'Too many accent hues', evidence: `${M.accentHues.length} distinct saturated hues (${M.accentHues.join('°, ')}°).`, why: 'A palette with one job per colour reads as decided; many accents dilute the one that should mark the primary action (Von Restorff: isolation only works if one thing is isolated).', source: `${SRC.restorff}; ${SRC.anthropic}`, suggestion: 'Reduce to one accent plus neutrals, or one accent and one semantic colour (error/success). Name each colour\'s single job.' });
  if (M.accentHues.length === 0 && !T.purpleGradient) add({ param: 'color', severity: 'P3', title: 'No accent colour at all', evidence: 'No saturated colour found in backgrounds, text or buttons.', why: 'Neutral palettes are legitimate (52% of strong sites have neutral primary buttons), but with no accent, hierarchy has to come from scale and space. Check that it does.', source: SRC.taste, suggestion: 'Either commit to monochrome and push type scale harder, or introduce one accent drawn from the subject matter.' });
  if (T.tintedBlack) add({ param: 'color', severity: 'P3', title: 'Tinted near-black ground (#0b0b0b / #111)', evidence: `Background ${M.bodyBg}.`, why: 'Near-black-but-not-black standing in for black is template chrome that appears regardless of subject.', source: SRC.anthropic, suggestion: 'Choose the ground on purpose: true black, a warm or cool dark drawn from the palette, or go light.' });
  const darkBg = (() => { const h = M.bodyBg.replace('#', ''); const l = (parseInt(h.slice(0, 2), 16) * 0.2126 + parseInt(h.slice(2, 4), 16) * 0.7152 + parseInt(h.slice(4, 6), 16) * 0.0722) / 255; return l < 0.25; })();
  if (darkBg && M.accentHues.some(h => h >= 80 && h <= 160) && M.accentHues.length === 1) add({ param: 'color', severity: 'P3', title: 'Dark ground + single acid-green accent', evidence: `Dark page with one accent at ${M.accentHues[0]}°.`, why: 'Named as a current AI cluster: near-black with one bright acid-green or vermilion accent, applied regardless of subject.', source: SRC.anthropic, suggestion: 'Keep it only if the subject justifies it (terminals, night, sport). Otherwise pick the accent from the subject\'s own material.' });

  // ======================= ACCESSIBILITY =======================
  const A = M.a11y;
  const axeV = (primary.axe?.violations || []);
  const axeById = Object.fromEntries(axeV.map(v => [v.id, v]));
  if (M.contrastFailCount > 0) {
    const worst = [...M.contrastFails].sort((a, b) => a.ratio - b.ratio).slice(0, 3);
    add({ param: 'accessibility', severity: M.contrastFailCount > 5 ? 'P0' : 'P1', title: 'Text fails WCAG contrast', evidence: `${M.contrastFailCount} text nodes below 4.5:1 (3:1 for large). Worst: ${worst.map(w => `"${w.text.slice(0, 30)}" ${w.ratio}:1 (${w.fg} on ${w.bg})`).join('; ')}.`, why: 'WCAG 2.2 SC 1.4.3 requires 4.5:1 for body text and 3:1 for large text. Grey-on-dark secondary text is the usual culprit and also the "text too faint" failure the study found on 13 of 54 weak sites.', source: `${SRC.wcag} 1.4.3; ${SRC.taste}`, suggestion: 'Raise secondary text to at least 4.5:1 against its real background. Running text should be in the full ink; reserve grey for genuinely secondary notes, and even then keep it legible.', cssPatch: (S.contrastFails || []).map(s => `${s}{color:${darkBg ? '#d6d6d6' : '#333'}!important;}`).join('\n') });
  }
  if (A.zoomBlocked) add({ param: 'accessibility', severity: 'P0', title: 'Zoom disabled in viewport meta', evidence: `meta viewport: "${A.viewportMeta}".`, why: 'user-scalable=no / maximum-scale=1 blocks pinch zoom, failing WCAG 1.4.4 (Resize text) and excluding low-vision users.', source: `${SRC.wcag} 1.4.4; ${SRC.vercel}`, suggestion: 'Use <meta name="viewport" content="width=device-width, initial-scale=1">.' });
  if (!A.lang) add({ param: 'accessibility', severity: 'P1', title: 'No lang attribute on <html>', evidence: 'html[lang] missing.', why: 'Screen readers pick pronunciation rules from it (WCAG 3.1.1).', source: `${SRC.wcag} 3.1.1`, suggestion: 'Add lang="en" (or the page language) to <html>.' });
  if (A.iconButtonsNoName > 0 || axeById['button-name'] || axeById['link-name']) add({ param: 'accessibility', severity: 'P1', title: 'Controls without an accessible name', evidence: `${A.iconButtonsNoName} icon-only buttons/links without aria-label${axeById['button-name'] ? `; axe button-name ×${axeById['button-name'].nodes}` : ''}${axeById['link-name'] ? `; axe link-name ×${axeById['link-name'].nodes}` : ''}.`, why: 'An icon button with no name is announced as "button". WCAG 4.1.2 (Name, Role, Value).', source: `${SRC.wcag} 4.1.2; ${SRC.vercel}`, suggestion: 'Give every icon-only control an aria-label that says what it does ("Open menu", not "hamburger").' });
  if (A.inputsNoLabel > 0 || axeById['label']) add({ param: 'accessibility', severity: 'P1', title: 'Form fields without labels', evidence: `${A.inputsNoLabel || axeById['label']?.nodes} fields with no <label>, aria-label or placeholder.`, why: 'WCAG 1.3.1 / 3.3.2. Placeholders alone vanish on input and usually fail contrast anyway.', source: `${SRC.wcag} 3.3.2`, suggestion: 'Add a visible <label for> to each field. Labels are clickable hit targets too (Fitts).' });
  if (M.outlineNone > 0 && M.focusVisibleRules === 0) add({ param: 'accessibility', severity: 'P1', title: 'Focus outline removed with no replacement', evidence: `${M.outlineNone} CSS rules set outline:none; 0 :focus-visible rules.`, why: 'Keyboard users cannot see where they are (WCAG 2.4.7 Focus Visible; 2.4.11 Focus Not Obscured in 2.2).', source: `${SRC.wcag} 2.4.7; ${SRC.vercel}`, suggestion: 'Replace with :focus-visible { outline: 2px solid <accent>; outline-offset: 2px }. Never outline:none without a visible alternative.', cssPatch: `:focus-visible{outline:2px solid var(--dc-accent,#1f4e5f)!important;outline-offset:2px!important;}` });
  if (phone && phone.metrics.a11y.smallTargets > 0) { const p = phone.metrics.a11y; add({ param: 'accessibility', severity: p.tinyTargets > 0 ? 'P1' : 'P2', title: p.tinyTargets > 0 ? 'Tap targets under the 24px WCAG floor on phone' : 'Tap targets under 44px on phone', evidence: `${p.tinyTargets || 0} of ${p.interactiveCount} interactive elements are under 24px in one dimension; ${p.smallTargets} are under the recommended 44px, at 390px.`, why: 'WCAG 2.5.8 sets 24px as the AA floor; Apple/Google guidance is 44–48px. Fitts\'s law: acquisition time grows as target size shrinks, and on a phone the pointer is a thumb.', source: `${SRC.wcag} 2.5.8; ${SRC.fitts}`, suggestion: 'Give links and buttons min-height 44px (padding, not font size) and 8px+ spacing between adjacent targets.', cssPatch: `@media (max-width:480px){a,button{min-height:44px;display:inline-flex;align-items:center;}}`, viewports: ['phone'] }); }
  if (A.headingSkips > 0 || A.h1Count !== 1) add({ param: 'accessibility', severity: 'P2', title: 'Heading structure is irregular', evidence: `${A.h1Count} <h1>; ${A.headingSkips} level skips (e.g. h2→h4).`, why: 'Headings are the table of contents for screen-reader users (WCAG 1.3.1). One h1, no skipped levels.', source: `${SRC.wcag} 1.3.1`, suggestion: 'Use exactly one h1 and step levels one at a time. Style with CSS, not by picking a heading level for its size.' });
  if (!A.landmarks.main) add({ param: 'accessibility', severity: 'P2', title: 'No <main> landmark', evidence: `main: ${A.landmarks.main}, nav: ${A.landmarks.nav}, footer: ${A.landmarks.footer}; skip link: ${A.skipLink}.`, why: 'Landmarks let assistive tech jump to content; a skip link does the same for keyboard users (WCAG 2.4.1 Bypass Blocks).', source: `${SRC.wcag} 2.4.1`, suggestion: 'Wrap page content in <main>, keep one <nav> and one <footer>, and add a "Skip to content" link as the first focusable element.' });
  if (A.missingAlt > 0) add({ param: 'accessibility', severity: 'P1', title: 'Images without alt attributes', evidence: `${A.missingAlt} of ${M.images.count} images have no alt.`, why: 'WCAG 1.1.1. Decorative images need alt="" so they are skipped; meaningful ones need a description.', source: `${SRC.wcag} 1.1.1`, suggestion: 'Add alt text that says what the picture is for in context, or alt="" for decoration.' });
  if (A.divClick > 0) add({ param: 'accessibility', severity: 'P2', title: 'Clickable <div>/<span> instead of <button>/<a>', evidence: `${A.divClick} elements.`, why: 'Divs are not focusable, have no role, and ignore Enter/Space. Semantic HTML before ARIA.', source: SRC.vercel, suggestion: 'Use <button> for actions and <a> for navigation.' });
  if (!M.reducedMotion && (M.animated > 0 || M.transitionAll > 0)) add({ param: 'accessibility', severity: 'P2', title: 'No prefers-reduced-motion rule', evidence: `${M.animated} animated elements, 0 reduced-motion media queries.`, why: 'WCAG 2.3.3 (Animation from Interactions). Vestibular users need motion to be optional.', source: `${SRC.wcag} 2.3.3; ${SRC.vercel}`, suggestion: 'Add @media (prefers-reduced-motion: reduce) { * { animation: none; transition: none } } or provide reduced variants.', cssPatch: `@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;}}` });
  for (const v of axeV.filter(v => !['color-contrast', 'button-name', 'link-name', 'label', 'html-has-lang', 'landmark-one-main', 'heading-order', 'meta-viewport', 'region', 'image-alt'].includes(v.id)).slice(0, 6)) {
    add({ param: 'accessibility', severity: v.impact === 'critical' ? 'P0' : v.impact === 'serious' ? 'P1' : 'P2', title: `axe: ${v.help}`, evidence: `${v.nodes} node(s), e.g. ${v.sample[0]?.target || ''}.`, why: v.sample[0]?.summary || 'Automated WCAG check failed.', source: `axe-core (${v.helpUrl})`, suggestion: 'Fix per the axe rule page; automated checks cover roughly 30% of WCAG, so follow with a manual pass.' });
  }

  // ======================= TYPOGRAPHY =======================
  const mainLower = mainFont.toLowerCase();
  const famCount = fontList.filter(([, c]) => c / totalChars >= 0.03).length;
  if (AI_FAVOURITE_FONTS.includes(mainLower) && mainFontShare > 0.8) add({ param: 'typography', rule: 'typography.ai-favourite-font-everywhere', severity: 'P1', title: `"${mainFont}" for everything`, evidence: `${mainFont} carries ${pct(fontList[0][1])}% of text; ${famCount} families carry 3%+.`, why: 'Inter (and its cousins Space Grotesk, DM Sans, Plus Jakarta, Manrope) at three weights with no real contrast is the typeface signature of generated pages. Type carries the personality of the page; a default face means no personality was chosen.', source: `${SRC.anthropic}; ${SRC.impeccable}; ${SRC.taste} (display classes: neo-grotesk 48%)`, suggestion: 'Pick one display face that belongs to the subject (a condensed grotesk, a transitional serif, an extended sans) and either keep it for everything or pair it with one clearly different text face. Decide, then push the scale.', cssPatch: `h1,h2,h3,.display{font-family:"Fraunces","Iowan Old Style",Georgia,serif!important;letter-spacing:-0.02em!important;font-weight:600!important;}` });
  else if (DEFAULT_FONTS.includes(mainLower) && mainFontShare > 0.8) add({ param: 'typography', rule: 'typography.default-font-everywhere', severity: 'P2', title: `System/default typeface "${mainFont}" carries the page`, evidence: `${pct(fontList[0][1])}% of text.`, why: 'A characterless default typeface was named as a failure on 13 of 54 weak sites in the study.', source: SRC.taste, suggestion: 'Choose a typeface deliberately for this subject, and set a type scale following Bringhurst (clear steps, intentional weights).' });
  if (famCount >= 3) add({ param: 'typography', severity: 'P2', title: 'Three or more typefaces', evidence: fontList.filter(([, c]) => c / totalChars >= 0.03).map(([f, c]) => `${f} ${pct(c)}%`).join(', '), why: 'One family, or two clearly distinct ones. Three reads as indecision (22% of studied sites, but rarely the strong ones).', source: `${SRC.anthropic}; ${SRC.bringhurst}`, suggestion: 'Cut to one or two families with distinct roles.' });
  const longMeasure = M.paragraphs.filter(p => p.cpl > 85);
  if (longMeasure.length >= 2) add({ param: 'typography', severity: 'P2', title: 'Line length over 85 characters', evidence: `${longMeasure.length} paragraphs; longest ≈${Math.max(...longMeasure.map(p => p.cpl))} chars/line at ${longMeasure[0].width}px wide.`, why: 'Bringhurst: 45–75 characters per line for a single column; 66 is the classic comfort point. Over ~80 the eye loses the return sweep. (WCAG 1.4.8 at AAA caps it at 80.)', source: `${SRC.bringhurst}; ${SRC.anthropic}`, suggestion: 'Set max-width on running text: 60–70ch for sans, slightly more for serif.', cssPatch: `p,li{max-width:68ch;}` });
  const tightLeading = M.paragraphs.filter(p => p.lineHeight < 1.35 && p.size <= 20);
  if (tightLeading.length >= 2) add({ param: 'typography', severity: 'P2', title: 'Body leading too tight', evidence: `${tightLeading.length} paragraphs at line-height < 1.35 (e.g. ${tightLeading[0].lineHeight} at ${tightLeading[0].size}px).`, why: 'Text sizes want 1.45–1.6 leading; serif body a little more than sans.', source: `${SRC.bringhurst}; ${SRC.taste}`, suggestion: 'Set body line-height 1.5 (1.55–1.6 for serif).', cssPatch: `p,li{line-height:1.55!important;}` });
  if (M.tinyChars / totalChars > 0.08) add({ param: 'typography', severity: 'P1', title: 'Text under 13px', evidence: `${pct(M.tinyChars)}% of characters are below 13px.`, why: 'Tiny text was a fault on 24 of the 90 best sites and 13 of 54 weak ones: the one thing both groups get wrong. Body wants 16px+; captions not below 13px.', source: `${SRC.taste}; ${SRC.wcag} 1.4.4`, suggestion: 'Raise minimum size to 13px (14px on phone) and body to 16–18px.', cssPatch: (S.tinyText || []).map(s => `${s}{font-size:13px!important;}`).join('\n') });
  if (M.hero && M.hero.sizeVw && M.hero.sizeVw < 3.5 && M.hero.words <= 12 && !primary.mobile) add({ param: 'typography', rule: 'typography.hero-timid', severity: 'P2', title: 'Hero type is timid', evidence: `h1 at ${M.hero.size}px = ${M.hero.sizeVw}vw at ${M.viewport.w}px; study median 5.0vw, top sites 6.0vw.`, why: 'Strong sites push extremes: their biggest type is bigger and the range wider. Weak sites cluster in the middle.', source: SRC.taste, suggestion: 'Either make the headline genuinely large (6–9vw, two lines or fewer) or make the hero about an image and keep the type quiet. Do not sit in between.', cssPatch: S.h1 ? `${S.h1}{font-size:clamp(2.5rem,7vw,7.5rem)!important;line-height:0.95!important;}` : undefined });
  const sizeCount = sizes.filter(([, c]) => c / totalChars > 0.01).length;
  if (sizeCount > 9) add({ param: 'typography', severity: 'P3', title: 'Type scale has too many steps', evidence: `${sizeCount} font sizes each carry >1% of text (study median 8; many strong sites use 2–3 with nothing between).`, why: 'A scale with clear steps is how hierarchy becomes legible. Many close sizes read as no scale.', source: `${SRC.bringhurst}; ${SRC.taste}`, suggestion: 'Collapse to 4–6 sizes with a deliberate ratio (e.g. 1.25 or 1.333), or 2–3 sizes with a big jump.' });
  const uppercaseHeadings = M.headings.filter(h => h.uppercase && h.size <= 14).length;

  // ======================= AI LOOK (weighted tells) =======================
  // Weights roughly follow how strongly the device separates weak from strong sites in the study.
  const tells = [];
  const tell = (cond, w, label, sel, patch) => { if (cond) tells.push({ w, label, sel, patch }); };
  tell(T.purpleGradient, 3, 'purple→blue gradient');
  tell(T.iconTiles > 0, 3, `${T.iconTiles} row(s) of icon-topped feature cards (28% weak vs 1% top)`, S.iconTiles, (S.iconTiles || []).map(s => `${s}{display:none!important;}`).join('\n'));
  tell(T.cardRows > 0 && T.iconTiles === 0, 1.5, `${T.cardRows} row(s) of identical boxed cards (26% weak vs 7% top)`);
  tell(T.trackedCaps >= 3, 2.5, `${T.trackedCaps} tiny tracked-caps labels (57% weak vs 16% top)`, S.trackedCaps, (S.trackedCaps || []).map(s => `${s}{text-transform:none!important;letter-spacing:0!important;font-size:0.95rem!important;}`).join('\n'));
  tell(T.trackedCaps > 0 && T.trackedCaps < 3, 1, `${T.trackedCaps} tracked-caps label(s)`);
  tell(T.pillAboveHeading > 0 || T.pills >= 2, 2, `${T.pills} pill badge(s), ${T.pillAboveHeading} directly above a heading (34% weak vs 14% top)`, S.pills, (S.pills || []).map(s => `${s}{display:none!important;}`).join('\n'));
  tell(T.eyebrows >= 3, 1.5, `${T.eyebrows} eyebrow labels above headings`, S.eyebrows);
  tell(T.gradientText > 0, 1.5, `${T.gradientText} gradient-text element(s) (13% weak vs 2% top)`);
  tell(T.shadows >= 5, 1.5, `${T.shadows} resting shadows (30% weak vs 10% top have five or more)`, S.shadows, (S.shadows || []).map(s => `${s}{box-shadow:none!important;}`).join('\n'));
  tell(T.emoji >= 2, 1.5, `${T.emoji} emoji in page text (26% weak vs 10% top)`);
  tell(T.indexNumbering >= 2, 1, `01/02/03 index numbering ×${T.indexNumbering}`, S.indexNumbering);
  tell(T.arrowLinks >= 2, 1, `"→" appended to ${T.arrowLinks} link/button labels`);
  tell(T.middleDots >= 1, 0.5, `meta strings joined with middle dots ×${T.middleDots}`);
  tell(T.backdropBlur >= 2 && T.gradients >= 2, 1, `${T.backdropBlur} frosted-glass (backdrop-filter) surfaces over gradients`, S.blurs, (S.blurs || []).map(s => `${s}{backdrop-filter:none!important;-webkit-backdrop-filter:none!important;}`).join('\n'));
  tell(M.hero && M.hero.centred && M.hero.buttonsBelow >= 1 && T.mediaCoverFrac < 0.3, 2.5, 'centred headline + buttons + mock/screenshot below (24% of weak heroes vs 7% of top)');
  tell(AI_FAVOURITE_FONTS.includes(mainLower) && mainFontShare > 0.8, 2, `${mainFont} as the only typeface`);
  tell(T.buzzwords >= 2, 1.5, `${T.buzzwords} buzzword phrases ("seamless", "unlock", "build the future"…)`);
  tell(T.tintedBlack, 0.5, 'tinted near-black ground');
  tell(M.radii && Object.keys(M.radii).filter(r => parseFloat(r) >= 12 && parseFloat(r) <= 24).reduce((a, k) => a + M.radii[k], 0) >= 6, 1, 'the same 12–24px radius on most boxes (the "soft" radius is the weak-site default; top sites are 52% square, 23% pill)');
  const tellScore = tells.reduce((a, t) => a + t.w, 0);
  const aiLook = clamp(10 - tellScore * 0.9);
  if (tells.length) add({ param: 'ai_look', rule: 'ai_look.tell-cluster', severity: tellScore >= 8 ? 'P0' : tellScore >= 4 ? 'P1' : 'P2', title: `${tells.length} generated-page tells (weighted ${r1(tellScore)})`, evidence: tells.map(t => '• ' + t.label).join('\n'), why: 'No single tell is proof; the cluster is. These devices appear regardless of subject, so they signal that no decision was made. The weights follow how strongly each device separates weak from strong sites in the 247-site study.', source: `${SRC.taste}; ${SRC.anthropic}; ${SRC.impeccable}`, suggestion: 'Remove the ornaments wholesale, then replace them with structure from space, tone and scale. Before adding a device back, state in one sentence what information it encodes about this content.', cssPatch: tells.map(t => t.patch).filter(Boolean).join('\n') });

  // ======================= PLACEMENT =======================
  const ctas = M.aboveFoldButtons || [];
  const primaryLike = ctas.filter(b => { const bg = b.bg || ''; return !b.inNav && !/rgba\(0, 0, 0, 0\)|transparent/.test(bg); });
  if (primaryLike.length >= 3) add({ param: 'placement', severity: 'P2', title: `${primaryLike.length} filled buttons compete above the fold`, evidence: primaryLike.map(b => `"${b.text}"`).join(', '), why: "Hick's law: decision time grows with the number of equally weighted choices. One primary action, everything else secondary.", source: `${SRC.hick}; ${SRC.nielsen} (aesthetic & minimalist design)`, suggestion: 'Keep one filled primary button in the first screen; demote the rest to text links or ghost buttons.' });
  if (M.hero && M.hero.words > 12) add({ param: 'hierarchy', rule: 'hierarchy.h1-is-a-paragraph', severity: 'P2', title: 'The h1 is a paragraph, not a headline', evidence: `${M.hero.words} words in the h1: "${M.hero.text.slice(0, 90)}…"`, why: 'Strong headlines run a median of 5 words. A statement this long can be a fine opening, but set as the h1 it is either too small to lead or too big to read. Mark it up as a statement paragraph (36px or less on desktop) and give the page a short headline, or let the name be the headline.', source: SRC.taste, suggestion: 'Split: a 2–8 word h1, then the statement as a <p> at statement size. No CSS can fix this; it is a copy decision.' });
  if (M.hero && M.hero.centred && M.hero.words > 9 && M.hero.words <= 12) add({ param: 'placement', rule: 'placement.long-centred-headline', severity: 'P2', title: 'Long centred headline', evidence: `${M.hero.words} words centred, ${M.hero.lines} lines at ${M.viewport.w}px.`, why: 'Centred text has a ragged left edge the eye must re-find on every line; it only works short. Study: centred alignment on 52% of weak sites vs 39% overall.', source: `${SRC.taste}; ${SRC.bringhurst}`, suggestion: 'Cut to ≤8 words (median strong headline: 5 words), or left-align and anchor it to a fixed off-centre line.', cssPatch: S.h1 ? `${S.h1}{text-align:left!important;max-width:24ch;margin-inline:0!important;}` : undefined });
  if (M.nav.exists && M.nav.links > 7) add({ param: 'placement', severity: 'P2', title: `${M.nav.links} navigation links`, evidence: `nav has ${M.nav.links} links (study median: 3).`, why: "Miller's law / chunking: 5–7 top-level choices is the comfortable limit; more should be grouped.", source: `${SRC.miller}; ${SRC.taste}`, suggestion: 'Group into ≤5 top-level items; move the rest to a footer or a disclosure menu.' });
  if (M.nav.exists && M.nav.sticky && M.nav.height > 90) add({ param: 'placement', severity: 'P3', title: 'Tall sticky header', evidence: `${M.nav.height}px fixed/sticky.`, why: 'Sticky chrome permanently steals viewport, worst on phones (WCAG 2.4.11: it must not obscure focused elements).', source: `${SRC.wcag} 2.4.11`, suggestion: 'Shrink on scroll or keep under ~64px.' });
  if (!M.nav.exists && M.screens > 3) add({ param: 'placement', severity: 'P3', title: 'No navigation on a long page', evidence: `${M.screens} screens tall, no <nav>/<header>.`, why: "Jakob's law: users expect to find a way around. Strong sites often drop the nav bar but keep corner links or a single anchor.", source: SRC.jakob, suggestion: 'Add minimal wayfinding: corner links, a progress indicator, or section anchors.' });
  if (M.hero && M.hero.y > M.viewport.h * 0.5) add({ param: 'placement', severity: 'P2', title: 'Headline sits below the middle of the first screen', evidence: `h1 top at ${M.hero.y}px of a ${M.viewport.h}px viewport.`, why: 'The first screen must say what the thing is. "Never saying what the thing is" sank 12 of 54 weak sites.', source: SRC.taste, suggestion: 'Bring the name or the headline into the top half, or let a full-bleed image carry the first screen with the title on it.' });

  // ======================= SPACE / NEGATIVE SPACE =======================
  const spacingVals = Object.entries(M.spacing).map(([v, c]) => [+v, c]).filter(([v, c]) => c >= 2);
  const offGrid = spacingVals.filter(([v]) => v % 4 !== 0).reduce((a, [, c]) => a + c, 0);
  const onGrid = spacingVals.reduce((a, [, c]) => a + c, 0);
  if (onGrid > 10 && offGrid / onGrid > 0.35) add({ param: 'space', severity: 'P2', title: 'Spacing values are off any grid', evidence: `${Math.round(100 * offGrid / onGrid)}% of repeated padding/margin/gap values are not multiples of 4 (${spacingVals.filter(([v]) => v % 4 !== 0).slice(0, 8).map(([v]) => v + 'px').join(', ')}).`, why: 'A spacing scale (4/8-based or a modular one) is what makes rhythm feel intentional; arbitrary values read as drift.', source: `${SRC.anthropic}; common 8pt-grid practice`, suggestion: 'Define 6–8 spacing tokens and use only those.' });
  if (spacingVals.length > 18) add({ param: 'space', severity: 'P3', title: 'Too many distinct spacing values', evidence: `${spacingVals.length} distinct repeated values.`, why: 'Same principle: a vocabulary of a few sizes, not a continuum.', source: SRC.anthropic, suggestion: 'Collapse to a token scale.' });
  if (M.sectionGaps.length >= 2) {
    const minGap = Math.min(...M.sectionGaps), maxGap = Math.max(...M.sectionGaps);
    const innerGaps = spacingVals.filter(([v]) => v >= 16 && v <= 64).length;
    if (minGap < 64 && innerGaps > 0) add({ param: 'space', severity: 'P2', title: 'Sections are not clearly separated from their insides', evidence: `Smallest gap between sections ${minGap}px; gaps inside sections run 16–64px.`, why: 'Gestalt proximity: the gap between groups must be clearly larger than any gap inside a group, or the grouping disappears. Strong sites: 120–240px between sections on desktop.', source: `${SRC.gestalt}; ${SRC.taste}`, suggestion: 'Make section spacing at least 2× the largest in-section gap (96–200px on desktop, 64–96px on phone).', cssPatch: `main > section, body > section{padding-block:clamp(64px,10vw,160px)!important;}` });
    if (maxGap > 0 && minGap > 0 && maxGap / minGap > 3) add({ param: 'space', severity: 'P3', title: 'Inconsistent section rhythm', evidence: `Section gaps range ${minGap}–${maxGap}px.`, why: 'Rhythm is repetition; a single planned exception reads as emphasis, random variation reads as error.', source: SRC.anthropic, suggestion: 'Use one section gap and one deliberate exception at most.' });
  }
  if (M.emptyScreens >= 2) add({ param: 'negative_space', severity: 'P1', title: `${M.emptyScreens} near-empty screens`, evidence: `${M.emptyScreens} viewport-height stretches with <40 characters and <15% media.`, why: 'Negative space is a tool for grouping and emphasis; a whole empty screen is a dead zone. The study\'s inspector fails a page with two or more near-empty screens.', source: SRC.taste, suggestion: 'Tighten those stretches or fill them with the subject (a picture, a live element). One rest per page is the limit.' });
  if (M.textAreaFrac > 0.45) add({ param: 'negative_space', severity: 'P2', title: 'Page is dense wall-to-wall', evidence: `Text covers ${Math.round(M.textAreaFrac * 100)}% of the page area.`, why: 'White space around a group tells the eye it is a group (proximity) and tells it what matters (isolation). Dense pages flatten hierarchy.', source: `${SRC.gestalt}; ${SRC.restorff}`, suggestion: 'Give the one thing per screen room; shorten the page if needed.' });
  const tightPadding = (T.cardRowDetails || []).length > 0 && spacingVals.some(([v, c]) => v <= 12 && c > 20);
  if (tightPadding) add({ param: 'negative_space', severity: 'P3', title: 'Cramped padding inside boxes', evidence: 'Many repeated paddings ≤12px alongside boxed card rows.', why: 'Boxes with thin padding make the border do work that space should do. Remove the box or widen the padding.', source: `${SRC.impeccable} (cramped padding rule)`, suggestion: 'Drop borders and let 32–48px of space group the content instead.' });
  const margins = (M.slabs || []).map(s => s.leftMargin).filter(v => v != null && v < M.viewport.w * 0.4);
  const rmargins = (M.slabs || []).map(s => s.rightMargin).filter(v => v != null && v < M.viewport.w * 0.4);
  if (margins.length >= 2 && rmargins.length >= 2) {
    const l = Math.min(...margins), rr = Math.min(...rmargins);
    if (Math.abs(l - rr) > 40 && !(M.hero && !M.hero.centred)) add({ param: 'space', severity: 'P3', title: 'Unequal outer margins', evidence: `Minimum left margin ${l}px, right ${rr}px.`, why: 'The frame: one pair of equal outer margins at every width. Unequal margins read as a section shoved to one side unless the asymmetry is the idea.', source: SRC.taste, suggestion: 'Set one container with equal inline padding; let large media run edge to edge instead.' });
  }

  // ======================= UX PRINCIPLES =======================
  if (M.copy.vagueButtons > 0 || A.genericLinks > 0) add({ param: 'ux_principles', severity: 'P2', title: 'Vague button and link labels', evidence: `${M.copy.vagueButtons} buttons like "Submit/Continue/Learn more"; ${A.genericLinks} generic links ("Click here", "Read more").`, why: "Nielsen #6 recognition over recall and #1 visibility of system status: a label should say exactly what happens. Screen-reader link lists also become useless.", source: `${SRC.nielsen}; ${SRC.anthropic}`, suggestion: 'Name the outcome: "Start 14-day trial", "See pricing", "Save changes".' });
  if (M.hero && M.hero.buttonsBelow >= 2 && M.aboveFoldButtons.length >= 2) { const b = M.aboveFoldButtons.slice(0, 2); if (b[0] && b[1] && b[0].bg === b[1].bg) add({ param: 'ux_principles', severity: 'P2', title: 'Two equal buttons in the hero', evidence: `"${b[0].text}" and "${b[1].text}" share the same treatment.`, why: 'Equal weight means no recommendation; the user must decide (Hick). One primary, one quiet alternative.', source: SRC.hick, suggestion: 'Make one filled, the other a text link.' }); }
  if (M.images.count === 0 && M.screens > 2 && T.mediaCoverFrac < 0.1 && M.images.videos === 0 && M.images.canvases === 0) add({ param: 'ux_principles', severity: 'P2', title: 'Nothing shows the product', evidence: 'No images, video or canvas anywhere on a multi-screen page.', why: 'Recognition over recall: show the thing. The strongest pages let the product demonstrate itself; the weakest never say what it is.', source: `${SRC.nielsen}; ${SRC.taste}`, suggestion: 'Put one real, working or photographed instance of the subject in the first screen.' });
  if (phone && phone.metrics.nav.exists && phone.metrics.nav.links > 4 && !phone.metrics.horizontalScroll) add({ param: 'ux_principles', severity: 'P3', title: 'Full desktop nav shown on phone', evidence: `${phone.metrics.nav.links} nav links visible at 390px.`, why: 'Jakob\'s law: phones expect a folded menu; many visible links at thumb size also fail Fitts.', source: `${SRC.jakob}; ${SRC.fitts}`, suggestion: 'Fold navigation into a disclosure on narrow screens, keeping the one primary action visible.', viewports: ['phone'] });

  // ======================= HIERARCHY =======================
  if (M.hero) {
    const ratio = M.hero.size / bodySize;
    if (ratio < 2.5) add({ param: 'hierarchy', severity: 'P2', title: 'Weak headline-to-body ratio', evidence: `h1 ${M.hero.size}px ÷ body ${bodySize}px = ${r1(ratio)} (study median 4.3; top sites 4.7).`, why: 'Hierarchy is contrast. If the headline is barely bigger than the text, nothing leads.', source: `${SRC.taste}; ${SRC.bringhurst}`, suggestion: 'Push the headline to 4–6× body, or shrink body to a comfortable 16–18px.' });
    if (M.hero.lines >= 3 && M.hero.words <= 12) add({ param: 'hierarchy', severity: 'P2', title: 'Headline runs to three or more lines', evidence: `${M.hero.lines} lines at ${M.viewport.w}px: "${M.hero.text.slice(0, 80)}"`, why: 'Two lines or fewer at every width: 70% of all studied sites meet it on desktop. Three lines of display type stop being a headline and become a paragraph.', source: SRC.taste, suggestion: 'Cut words first, widen the measure second, reduce size last.' });
  }
  const h2s = M.headings.filter(h => h.tag === 'h2');
  if (h2s.length >= 3 && h2s.every(h => h.align === 'center')) add({ param: 'hierarchy', severity: 'P3', title: 'Every section heading centred', evidence: `${h2s.length} h2s, all centred.`, why: 'When every section is composed the same way nothing is emphasised. Strong pages recompose sections and anchor text to a fixed off-centre line.', source: SRC.taste, suggestion: 'Left-anchor section headings to the page grid; centre only the one moment that deserves it.', cssPatch: `h2{text-align:left!important;}` });
  if (T.cardRows >= 2) add({ param: 'hierarchy', severity: 'P2', title: 'Content chopped into equal cards', evidence: `${T.cardRows} rows of identical boxes (${(T.cardRowDetails || []).map(d => d.count).join(', ')} items).`, why: 'Equal boxes say "these are equal". Usually they are not: one feature matters most, one stat is the point. Common region (Gestalt) is the strongest grouping cue, so cards also override every other hierarchy on the page.', source: `${SRC.gestalt}; ${SRC.anthropic}`, suggestion: 'Rank the items. Give the first one scale and the rest a list; drop the boxes and let space and a change of ground group them.', cssPatch: (S.cardRows || []).map(s => `${s} > *{background:transparent!important;border:0!important;box-shadow:none!important;backdrop-filter:none!important;}`).join('\n') });

  // ======================= COPY =======================
  if (T.buzzwords > 0) add({ param: 'copy', severity: T.buzzwords >= 3 ? 'P1' : 'P2', title: 'Buzzword copy', evidence: `${T.buzzwords} phrases matching seamless / unlock / empower / elevate / build the future / cutting-edge / all-in-one. Headline: "${M.hero?.text || ''}".`, why: 'Copy can make a design feel as templated as the design. "Build the future" and "Everything you need" could head any product; specific, literal naming of what the thing does is what the study\'s jurors rewarded.', source: `${SRC.anthropic}; ${SRC.taste}`, suggestion: 'Rewrite the headline as a plain statement of what the product is and for whom, in ≤8 words. Replace each buzzword with the concrete thing it hides.' });
  if (T.loremIpsum > 0) add({ param: 'copy', severity: 'P1', title: 'Placeholder text shipped', evidence: `${T.loremIpsum} lorem-ipsum blocks.`, why: 'Placeholder content means the layout was never tested against real content lengths.', source: SRC.vercel, suggestion: 'Write real copy; then re-check wrapping at short, average and long lengths.' });
  if (M.hero && /\b(everything you need|all[- ]in[- ]one|the future|next generation|reimagined)\b/i.test(M.hero.text)) add({ param: 'copy', severity: 'P2', title: 'Category-generic headline', evidence: `"${M.hero.text}"`, why: 'A headline that any competitor could run says nothing. The competitor test: if a rival could paste it unchanged, it is not yours.', source: SRC.taste, suggestion: 'Name the subject and the one claim only it can make.' });

  // ======================= MOTION =======================
  if (M.transitionAll > 0) add({ param: 'motion', severity: M.transitionAll > 20 ? 'P1' : 'P2', title: 'transition: all', evidence: `${M.transitionAll} elements transition every property.`, why: 'Transitions every layout property (jank) and animates things you did not intend. List properties explicitly; animate transform/opacity only.', source: SRC.vercel, suggestion: 'transition: transform .2s, opacity .2s, background-color .2s.' });
  if (M.animated >= 6 && M.animated < 40) add({ param: 'motion', severity: 'P3', title: 'Scattered entrance animations', evidence: `${M.animated} elements carry CSS animations after load.`, why: 'Fade-and-slide-up on every section and hover lift on every card is the generic default. One orchestrated moment lands better than scattered effects.', source: SRC.anthropic, suggestion: 'Keep one page-load sequence or one reveal; make all other motion answer a user action.' });
  if (M.animated === 0 && M.transitionAll === 0 && M.screens > 3 && M.images.videos === 0 && M.images.canvases === 0) add({ param: 'motion', severity: 'P3', title: 'No motion at all', evidence: 'No animations, transitions, video or canvas detected.', why: 'Legitimate (about 10 strong sites show little or no motion), but interaction feedback on hover/press is a usability floor.', source: `${SRC.taste}; ${SRC.vercel}`, suggestion: 'Add hover/active feedback on controls and, if it serves the subject, one live element.' });

  // ======================= CONSISTENCY =======================
  const radiusKeys = Object.entries(M.radii).filter(([, c]) => c >= 2).map(([k]) => k);
  if (radiusKeys.length >= 5) add({ param: 'consistency', severity: 'P2', title: `${radiusKeys.length} different border radii`, evidence: radiusKeys.join(', '), why: 'Radius is a vocabulary word; a design uses two or three (none / small / pill), chosen by hierarchy, not per element.', source: `${SRC.anthropic}; ${SRC.taste} (button shape decided once)`, suggestion: 'Pick a radius for controls and one for surfaces; apply nothing else.' });
  const uniqShadows = (T.shadowSamples || []).length;
  if (uniqShadows >= 4) add({ param: 'consistency', severity: 'P3', title: `${uniqShadows} distinct shadow recipes`, evidence: T.shadowSamples.join(' | '), why: 'Shadows imply a light source; several recipes imply several suns.', source: SRC.anthropic, suggestion: 'One elevation scale (two or three levels), or none.' });
  if (phone && phone.metrics && Object.keys(phone.metrics.fonts)[0] && Object.keys(M.fonts)[0] && Object.keys(phone.metrics.fonts)[0] !== Object.keys(M.fonts)[0]) add({ param: 'consistency', severity: 'P2', title: 'Different primary typeface on phone vs desktop', evidence: `${Object.keys(phone.metrics.fonts)[0]} at 390px vs ${Object.keys(M.fonts)[0]} at ${M.viewport.w}px.`, why: 'Usually a web-font load failure on one breakpoint; the brand should look the same everywhere.', source: SRC.vercel, suggestion: 'Preload the font; check font-display and fallback stacks.' });

  // ======================= IMAGERY =======================
  const realMedia = M.images.visibleCount + M.images.videos + M.images.canvases;
  if (realMedia === 0 && M.screens > 1.5) add({ param: 'imagery', severity: 'P1', title: 'No pictures or footage', evidence: `0 visible images/videos/canvases over ${M.screens} screens (study: median 24 images; top sites 37, weak 5).`, why: 'Models skip pictures because finding them is work, and the page fails without them. Imagery is where the subject enters the design.', source: SRC.taste, suggestion: 'Add at least four real pictures of the subject (open-licence archives if nothing else), one of them carrying the first screen.' });
  else if (realMedia > 0 && realMedia < 4 && M.screens > 3) add({ param: 'imagery', severity: 'P2', title: 'Very little imagery', evidence: `${realMedia} media elements over ${M.screens} screens.`, why: 'Weak sites had a median of 5 images; strong ones 37.', source: SRC.taste, suggestion: 'Let the subject appear: product in use, place, material, people.' });
  if (T.mediaCoverFrac < 0.2 && M.hero && !M.hero.centred === false && realMedia > 0 && M.screens > 2) add({ param: 'imagery', severity: 'P3', title: 'First screen has no dominant image', evidence: `Media covers ${Math.round(T.mediaCoverFrac * 100)}% of the first viewport (hero media covers ≥50% on 68% of top sites).`, why: 'Full-bleed media with type over it is the commonest strong hero; a floating product mock under a centred headline is the weak one.', source: SRC.taste, suggestion: 'Let one picture or live element fill the first screen, or go fully typographic at scale.' });
  if (M.images.svgIllustrations >= 3 && M.images.visibleCount === 0) add({ param: 'imagery', severity: 'P2', title: 'Flat vector illustrations instead of pictures', evidence: `${M.images.svgIllustrations} large inline SVGs, 0 photographs.`, why: 'Illustration-led pages scored lowest in the study (median 6.9) and generic flat vectors are a frequent AI tell.', source: SRC.taste, suggestion: 'Replace with photography or a product demonstration; keep illustration only if it is drawn in a style owned by the brand.' });
  if (M.images.aspectRatios.length >= 4) { const u = new Set(M.images.aspectRatios.map(r => Math.round(r * 4) / 4)); if (u.size > Math.min(5, M.images.aspectRatios.length * 0.6)) add({ param: 'imagery', severity: 'P3', title: 'Inconsistent image crops', evidence: `${u.size} distinct aspect ratios across ${M.images.aspectRatios.length} images.`, why: 'Same crop ratios and same treatment make a set; random ratios make a pile.', source: SRC.taste, suggestion: 'Choose one or two ratios and crop to them.' }); }

  // ======================= RESPONSIVE =======================
  for (const v of vps) {
    const m = v.metrics;
    if ((m.horizontalScroll && !m.scoped) || m.overflowEls > 0) add({ param: 'responsive', severity: m.horizontalScroll && !m.scoped ? 'P0' : 'P2', title: `Horizontal overflow at ${v.width}px`, evidence: `scrollWidth ${m.scrollWidth} vs viewport ${v.width}; ${m.overflowEls} elements extend past the right edge${(m.selectors?.overflow || []).length ? ` (${m.selectors.overflow.slice(0, 3).join(', ')})` : ''}.`, why: 'Horizontal scroll on a phone is the most visible responsive failure; it usually means a fixed pixel width or an un-wrapped flex row.', source: SRC.vercel, suggestion: 'Replace fixed widths with max-width:100%; allow flex-wrap; set min-width:0 on flex children; hide overflow-x only as a last resort.', cssPatch: `img,video,svg,iframe{max-width:100%;}\n${(m.selectors?.overflow || []).map(s => `${s}{max-width:100%!important;width:auto!important;}`).join('\n')}`, viewports: [v.name] });
    if (m.hero && m.hero.lines >= 3 && v.mobile) add({ param: 'responsive', severity: 'P2', title: `Headline wraps to ${m.hero.lines} lines at ${v.width}px`, evidence: `h1 ${m.hero.size}px (${m.hero.sizeVw}vw) "${m.hero.text.slice(0, 60)}"`, why: 'Three lines or fewer on a phone is met by 82% of studied sites; type that does not scale down reads as a desktop page squeezed.', source: SRC.taste, suggestion: 'Use clamp() for display sizes (e.g. clamp(2rem, 8vw, 6rem)) and cut words.', cssPatch: m.selectors?.h1 ? `@media (max-width:${v.width + 40}px){${m.selectors.h1}{font-size:clamp(1.75rem,8vw,4rem)!important;line-height:1.05!important;}}` : undefined, viewports: [v.name] });
    if (v.name === 'phone' && m.tinyChars / Math.max(1, m.totalChars) > 0.1) add({ param: 'responsive', severity: 'P2', title: `Small text at ${v.width}px`, evidence: `${Math.round(100 * m.tinyChars / m.totalChars)}% of text under 13px.`, why: 'Text should not shrink on phones; if anything it grows (16px body minimum avoids iOS zoom-on-focus too).', source: `${SRC.wcag} 1.4.4`, suggestion: 'Body 16px+ on phone; captions ≥13px.', viewports: [v.name] });
    if (v.mobile && m.paragraphs.some(p => p.cpl < 25 && p.lines > 6)) add({ param: 'responsive', severity: 'P3', title: `Very narrow text columns at ${v.width}px`, evidence: 'Paragraphs wrapping at <25 characters per line.', why: 'Multi-column layouts that do not collapse produce ribbon-thin columns on phones.', source: SRC.bringhurst, suggestion: 'Stack columns below 768px.', viewports: [v.name] });
  }
  if (M.mediaQueries === 0 && M.containerQueries === 0 && M.clampUsage === 0 && vps.length > 1) add({ param: 'responsive', severity: 'P1', title: 'No responsive CSS detected', evidence: '0 media queries, 0 container queries, 0 clamp() in accessible stylesheets.', why: 'The design cannot be consistent across sizes if nothing adapts.', source: SRC.vercel, suggestion: 'Add breakpoints at least at 480 and 1024, and fluid type with clamp().' });
  if (by.desktop && by.laptop) {
    const d = by.desktop.metrics, l = by.laptop.metrics;
    const widestPara = Math.max(0, ...d.paragraphs.map(p => p.width));
    if (widestPara > 1100) add({ param: 'responsive', severity: 'P2', title: 'Running text stretches too wide at 1920px', evidence: `Widest paragraph ${widestPara}px at 1920.`, why: 'Line length explodes on large screens without a max-width; the 45–75 character measure is the constraint.', source: SRC.bringhurst, suggestion: 'Cap the text container (e.g. 72ch) or add a column structure for wide screens.', cssPatch: `p,li{max-width:72ch;}`, viewports: ['desktop'] });
    if (d.hero && l.hero && d.hero.size === l.hero.size && d.hero.sizeVw < 3) add({ param: 'responsive', severity: 'P3', title: 'Display type does not scale up on large screens', evidence: `h1 ${d.hero.size}px at both 1440 and 1920 (${d.hero.sizeVw}vw at 1920).`, why: 'Fixed pixel display sizes look small on big monitors; fluid type keeps the composition.', source: SRC.taste, suggestion: 'Use clamp() with a vw middle term for display sizes.', viewports: ['desktop'] });
  }
  if (phone && M.hero && phone.metrics.hero && phone.metrics.hero.centred !== M.hero.centred) add({ param: 'responsive', severity: 'P3', title: 'Hero alignment changes between phone and desktop', evidence: `centred: phone ${phone.metrics.hero.centred}, desktop ${M.hero.centred}.`, why: 'Changing alignment per breakpoint is fine if deliberate; often it is an accident of a centred mobile stack.', source: SRC.anthropic, suggestion: 'Decide the alignment once and keep it, or make the change intentional.' });

  // ======================= CRAFT =======================
  if (M.images.count > 0 && M.images.missingDims / M.images.count > 0.5) add({ param: 'craft', severity: 'P2', title: 'Images without width/height', evidence: `${M.images.missingDims}/${M.images.count} images lack intrinsic dimensions.`, why: 'Causes layout shift (CLS) as images load; the page jumps under the reader.', source: SRC.vercel, suggestion: 'Set width and height attributes (or aspect-ratio in CSS).' });
  if (M.images.belowFold > 3 && M.images.lazyBelowFold === 0) add({ param: 'craft', severity: 'P3', title: 'Below-fold images not lazy-loaded', evidence: `${M.images.belowFold} images below the first screen, none with loading="lazy".`, why: 'Wasted bandwidth and slower first paint.', source: SRC.vercel, suggestion: 'Add loading="lazy" below the fold; fetchpriority="high" on the hero image.' });
  const errs = vps.flatMap(v => v.consoleErrors || []);
  if (errs.length) add({ param: 'craft', severity: 'P2', title: 'JavaScript errors on load', evidence: [...new Set(errs)].slice(0, 3).join(' | '), why: 'Errors often leave reveal-on-scroll content permanently hidden.', source: SRC.taste, suggestion: 'Fix the errors; never gate content visibility on a script.' });
  const slow = vps.filter(v => v.loadMs > 6000);
  if (slow.length) add({ param: 'craft', severity: 'P3', title: 'Slow load', evidence: slow.map(v => `${v.name}: ${(v.loadMs / 1000).toFixed(1)}s`).join(', '), why: 'Aesthetic-usability only holds if the page arrives.', source: SRC.lawsux, suggestion: 'Compress media, preload the hero font and image, defer scripts.' });

  // ======================= CREATIVITY (heuristic; judge refines) =======================
  const creativeSignals = [];
  if (M.hero && M.hero.centred && M.hero.buttonsBelow >= 1 && T.mediaCoverFrac < 0.3) creativeSignals.push('stock hero (centred statement, buttons, mock below)');
  if (T.iconTiles > 0) creativeSignals.push('feature-card module');
  if (M.distinctSectionGrounds <= 1 && M.screens > 3) creativeSignals.push('single ground colour across the whole page');
  if (realMedia === 0) creativeSignals.push('no imagery from the subject');
  if (!AI_FAVOURITE_FONTS.includes(mainLower) && !DEFAULT_FONTS.includes(mainLower)) creativeSignals.push('+ a chosen typeface');
  if (M.images.videos + M.images.canvases > 0) creativeSignals.push('+ live media (video/canvas)');
  if (M.distinctSectionGrounds >= 3) creativeSignals.push('+ several section grounds');
  const negatives = creativeSignals.filter(s => !s.startsWith('+')).length, positives = creativeSignals.length - negatives;
  add({ param: 'creativity', rule: 'creativity.concept-check', severity: negatives >= 3 ? 'P1' : negatives >= 1 ? 'P2' : 'P3', title: negatives >= 2 ? 'Reads as the category template' : 'Concept check', evidence: creativeSignals.length ? creativeSignals.join('; ') : 'No strong template signals measured.', why: 'The clearest pattern in the study: high scores go with a concept taken from the subject ("the product demonstrates itself", "the page is an artefact from the subject\'s world", "the name is the hero"); low scores go with its absence ("the standard dark SaaS launch formula"). Heuristics can only detect the absence; a reviewer must judge the presence.', source: `${SRC.taste}; ${SRC.anthropic}`, suggestion: 'Write one sentence tying this subject\'s own material to a visual idea no competitor could paste. Spend the boldness in one place; keep everything else quiet.', needsJudge: true });

  // ======================= SCOPED (component) MODE =======================
  // Page-level judgements make no sense for one component; drop them and mark their parameters unscored.
  const scoped = !!M.scoped;
  const PAGE_LEVEL = /^(placement\.|negative_space\.|imagery\.|creativity\.|craft\.|copy\.category-generic|typography\.hero-timid|hierarchy\.the-h-is-a-paragraph|hierarchy\.headline-runs|hierarchy\.every-section|space\.sections|space\.inconsistent-section|space\.unequal|accessibility\.no-main|accessibility\.no-lang|accessibility\.heading-structure|accessibility\.zoom|ux_principles\.nothing-shows|ux_principles\.full-desktop|ux_principles\.two-equal|responsive\.no-responsive|responsive\.headline-wraps|responsive\.running-text|responsive\.display-type|responsive\.hero-alignment|motion\.no-motion|consistency\.different-primary)/;
  const UNSCORED_WHEN_SCOPED = new Set(['placement', 'negative_space', 'imagery', 'creativity', 'craft']);
  if (scoped) for (let i = findings.length - 1; i >= 0; i--) if (PAGE_LEVEL.test(findings[i].rule)) findings.splice(i, 1);

  // ======================= SCORES =======================
  const scores = {};
  for (const p of PARAMETERS) {
    const fs = findings.filter(f => f.param === p.id);
    let s = 10 - fs.reduce((a, f) => a + SEV[f.severity], 0);
    if (p.id === 'ai_look') s = aiLook;
    if (p.id === 'creativity') s = clamp(7.5 - negatives * 1.5 + positives * 0.75);
    scores[p.id] = { score: r1(clamp(s)), findings: fs.length, provisional: p.id === 'creativity' || p.id === 'ai_look' };
    if (scoped && UNSCORED_WHEN_SCOPED.has(p.id)) scores[p.id] = { score: null, findings: 0, unscored: 'page-level; not scored for a component' };
  }
  const weights = { accessibility: 1.5, ai_look: 1.3, typography: 1.2, hierarchy: 1.1, responsive: 1.1, creativity: 1.0, color: 1, placement: 1, space: 0.8, negative_space: 0.8, ux_principles: 1, copy: 0.8, motion: 0.6, consistency: 0.7, imagery: 0.9, craft: 0.5 };
  const scoredEntries = Object.entries(scores).filter(([, v]) => v.score != null);
  const overall = r1(scoredEntries.reduce((a, [k, v]) => a + v.score * (weights[k] || 1), 0) / scoredEntries.reduce((a, [k]) => a + (weights[k] || 1), 0));

  // Design-token proposal (used by the prompt generator): what we observed, what we'd change.
  const observed = { typeface: mainFont, families: fontList.slice(0, 3).map(([f, c]) => `${f} (${pct(c)}%)`), bodySize, heroSize: M.hero?.size, ground: M.bodyBg, accents: M.accents, radii: radiusKeys, sectionGaps: M.sectionGaps };

  return { overall, scores, findings: findings.sort((a, b) => SEV[b.severity] - SEV[a.severity]), observed, tells: tells.map(t => t.label), summary: { viewports: vps.map(v => `${v.name} ${v.width}×${v.height}`), url: capture.url, title: M.copy.title, selector: capture.selector || null, scoped } };
}
